def identity(raw,kind):
    if kind not in ('inputs','outputs','runs','records','compilers'):raise ValueError('Reviewed artifact class required')
    return {'key':model.PREFIX+kind+'/'+model.sha(raw)+('.py' if kind=='compilers' else '.json'),'sha256':model.sha(raw),'bytes':len(raw)}
def put_immutable(client,bucket,key,raw):
    if not isinstance(raw,bytes) or not 0<len(raw)<=MAX or not artifact_key(key) or not key.startswith(model.PREFIX) or key.rsplit('/',1)[-1].split('.')[0]!=model.sha(raw):raise ValueError('Exact immutable public research artifact required')
    try:client.put_object(Bucket=bucket,Key=key,Body=raw,ContentType='text/x-python' if key.endswith('.py') else 'application/json',CacheControl='public, max-age=31536000, immutable',IfNoneMatch='*')
    except Exception as exc:
        if not conflict(exc):raise
    if bounded(client.get_object(Bucket=bucket,Key=key)['Body'])!=raw:raise ValueError('Immutable artifact readback differs')
def checked(ref,kind,read):
    if not isinstance(ref,dict) or not artifact_key(ref.get('key')):raise ValueError('Artifact identity required')
    raw=read(ref['key'])
    if identity(raw,kind)!=ref:raise ValueError('Recorded '+kind+' differs')
    return model.strict(raw)
def retain(client,bucket,inputs,compiled):
    packet=compiled['packet'];shards=compiled['shards']
    if set(packet['record_shards'])!=set(shards):raise ValueError('Exact record-shard index required')
    # Validate the entire artifact set before the first write.
    records=[]
    for key,shard in sorted(shards.items()):
        raw=model.encoded(shard);ref=identity(raw,'records')
        if ref!=packet['record_shards'][key] or len(raw)>MAX:raise ValueError('Record shard differs')
        records.append((ref['key'],raw))
    for doc in (inputs,packet):
        if len(model.encoded(doc))>MAX:raise ValueError('Manifest bound exceeded')
    def write(item):put_immutable(client,bucket,*item)
    with ThreadPoolExecutor(max_workers=4) as pool:
        for _ in pool.map(write,records):pass
    refs={}
    for kind,doc in (('inputs',inputs),('outputs',packet)):
        raw=model.encoded(doc);ref=identity(raw,kind);put_immutable(client,bucket,ref['key'],raw);refs[kind[:-1]]=ref
    compilers={}
    for module in COMPILERS:
        raw=Path(module.__file__).read_bytes();ref=identity(raw,'compilers');put_immutable(client,bucket,ref['key'],raw);compilers[module.__name__]=ref
    run={'contract':'offexchange-original-replay.v1','generated_at':packet['generated_at'],**refs,'compilers':compilers,'output_sha256':refs['output']['sha256']}
    raw=model.encoded(run);ref=identity(raw,'runs');put_immutable(client,bucket,ref['key'],raw)
    return {'manifest_key':ref['key'],'output_sha256':refs['output']['sha256']}
def verified_run(ref,read):
    if not isinstance(ref,dict) or set(ref)!={'manifest_key','output_sha256'} or not isinstance(ref['manifest_key'],str) or not re.fullmatch(re.escape(model.PREFIX)+r'runs/[a-f0-9]{64}\.json',ref['manifest_key']):raise ValueError('Immutable off-exchange run required')
    raw=read(ref['manifest_key']);run=model.strict(raw)
    if identity(raw,'runs')['key']!=ref['manifest_key'] or run.get('contract')!='offexchange-original-replay.v1' or run.get('output_sha256')!=ref['output_sha256']:raise ValueError('Recorded run differs')
    if set(run.get('compilers',{}))!={m.__name__ for m in COMPILERS}:raise ValueError('Exact compiler set required')
    for module in COMPILERS:
        raw=Path(module.__file__).read_bytes();expected=identity(raw,'compilers')
        if run['compilers'][module.__name__]!=expected or read(expected['key'])!=raw:raise ValueError('Matching frozen compiler checkout required')
    return run
def replay(ref,read):
    run=verified_run(ref,read);inputs=checked(run['input'],'inputs',read);expected=checked(run['output'],'outputs',read)
    compiled=model.compile_output(inputs,read)
    if compiled['packet']!=expected or model.digest(expected)!=run['output_sha256'] or expected['generated_at']!=run['generated_at']:raise ValueError('Original-source reconstruction differs')
    for key,shard in compiled['shards'].items():
        if checked(expected['record_shards'][key],'records',read)!=shard:raise ValueError('Recorded shard differs')
    return compiled
